name: Codex Review Notify Code Owner

on:
  pull_request:
    branches: [epic, develop]
    types: [opened, synchronize, reopened]

jobs:
  test:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'

      - name: Install dependencies
        run: npm ci

      - name: Run Vitest tests
        run: npm run test:ci

      - name: Upload test results
        uses: dorny/test-reporter@v1
        if: always()
        with:
          name: Vitest
          path: ./test-results.xml
          reporter: jest

      - name: Notify Code Owners
        if: success()
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs');
            const path = require('path');
            const codeownersPath = path.join(process.env.GITHUB_WORKSPACE, '.github/CODEOWNERS');
            if (!fs.existsSync(codeownersPath)) {
              console.log('No CODEOWNERS file found.');
              return;
            }
            const content = fs.readFileSync(codeownersPath, 'utf8');
            const lines = content.split('\n');
            const owners = new Set();
            for (const line of lines) {
              const trimmed = line.trim();
              if (!trimmed || trimmed.startsWith('#')) continue;
              const parts = trimmed.split(/\s+/);
              const ownerPart = parts[parts.length - 1];
              const ownerMatches = ownerPart.match(/@[\w-]+/g);
              if (ownerMatches) {
                ownerMatches.forEach(o => owners.add(o));
              }
            }
            if (owners.size === 0) {
              console.log('No owners found in CODEOWNERS.');
              return;
            }
            const reviewers = Array.from(owners);
            console.log('Requesting review from:', reviewers);
            await github.rest.pulls.requestReviewers({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number,
              reviewers: reviewers
            });
